"""Provider profiles and explicit Moments targets on the shared offline UI."""

STYLE = '''<style>
textarea{font:inherit;color:var(--ink);width:100%;min-height:110px;padding:12px;border:1px solid var(--line);border-radius:8px;resize:vertical}textarea:focus-visible{outline:3px solid #51bda1;outline-offset:3px}.contact-list{max-height:260px;overflow:auto;border:1px solid var(--line);border-radius:9px;margin:12px 0}.contact-choice{display:flex;align-items:center;gap:12px;min-height:48px;padding:9px 14px;border-bottom:1px solid #edf2ef;cursor:pointer}.contact-choice:last-child{border:0}.contact-choice input{min-height:20px;width:20px;accent-color:var(--green)}.selection-summary{font-size:12px;color:var(--green);margin:8px 0}.provider-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:22px}.provider-grid select,.provider-grid input{width:100%}.wide{grid-column:1/-1}.live-ai{padding:13px 16px;border:1px solid var(--line);border-radius:8px;margin-bottom:16px;color:var(--muted)}.compact-field{margin-bottom:12px}.provider-grid pre{min-height:140px;max-height:350px;border-radius:8px}.source-note{font-size:12px;color:var(--muted)}@media(max-width:1000px){.provider-grid{grid-template-columns:1fr}}
.provider-grid{align-items:start}.provider-grid .contact-choice input{width:20px;flex:0 0 20px}.contact-choice span{flex:1;min-width:0;overflow-wrap:anywhere}
</style>'''

NAV = '''<button role="tab" id="tab-targets" aria-controls="view-targets" aria-selected="false" data-view="targets"><span>05</span>朋友圈用户</button><button role="tab" id="tab-ai" aria-controls="view-ai" aria-selected="false" data-view="ai"><span>06</span>AI 智能答复</button>'''

PANELS = '''<section id="view-targets" role="tabpanel" aria-labelledby="tab-targets" hidden>
<div class="section-intro"><h2>选择要点赞的用户</h2><p class="sub">所选名单用于“定点点赞”任务。每轮每位用户最多定位一条匹配动态，其他原有任务按各自脚本规则执行。</p></div>
<div class="workspace"><div class="panel"><div class="panel-head"><h2>用户名单</h2><button id="targets-read">从微信读取联系人</button></div><div class="panel-body"><label class="label" for="target-search">搜索用户</label><input id="target-search" placeholder="输入昵称或备注筛选" style="width:100%"><div id="target-list" class="contact-list"><div class="empty">先连接电脑，或手动添加用户。</div></div><p id="target-summary" class="selection-summary">尚未选择用户</p><label class="label" for="target-manual">手动添加，每行一个与微信一致的昵称或备注</label><textarea id="target-manual" placeholder="每行填写一个用户，不会自动选择其他用户。"></textarea><div class="actions" style="margin-top:12px"><button id="targets-add">添加并选中</button><button id="targets-clear">清空选择</button></div><p class="source-note">读取联系人会在电脑调用 SDK，可能切换微信界面；不读取账号密码或数据库密钥。</p></div></div>
<div class="panel"><div class="panel-head"><h2>定点任务参数</h2></div><div class="panel-body"><label class="label" for="target-keyword">正文关键词 / 可选</label><input id="target-keyword" placeholder="同时按作者和关键词匹配" maxlength="200" style="width:100%"><div class="hint">名单按名字精确匹配。同名用户无法仅凭昵称区分，开始前请核对备注。保存名单不会自动点赞。</div><div class="actions"><button id="targets-save" class="primary">保存选择</button><button id="targets-start" disabled>启动定点任务</button></div><p id="targets-state" class="sub" role="status">请先保存选择。</p></div></div></div></section>

<section id="view-ai" role="tabpanel" aria-labelledby="tab-ai" hidden><div class="section-intro"><h2>AI 服务商与智能答复</h2><p class="sub">参考 CC Switch 的方案管理方式。保存多个服务商，切换当前方案，先用样例消息预览回复。</p></div><div id="ai-state" class="live-ai" role="status">连接电脑并启动 C# SDK 后读取配置。</div><div class="actions" style="margin-bottom:18px"><button id="ai-sdk-start">启动 SDK 服务</button><button id="ai-reload">刷新配置</button><button id="ai-import">导入配置 JSON</button><button id="ai-export">导出配置 / 不含密钥</button><input id="ai-import-file" type="file" accept=".json,application/json" hidden></div>
<div class="provider-grid"><div class="panel"><div class="panel-head"><h2>服务商方案</h2><button id="ai-new">新增方案</button></div><div class="panel-body"><label class="label" for="ai-profile">选择方案</label><select id="ai-profile"></select><p id="ai-active" class="selection-summary">尚未加载</p><div class="form-grid"><label class="field"><span class="label">方案名称</span><input id="ai-name" maxlength="80"></label><label class="field"><span class="label">接口协议</span><select id="ai-protocol"><option value="openai-compatible">OpenAI 兼容 Chat Completions</option><option value="ollama">Ollama 本地接口</option></select></label></div><label class="label" for="ai-url">API Base URL</label><input id="ai-url" placeholder="https://你的服务地址/v1" inputmode="url"><label class="label" for="ai-model" style="margin-top:12px">模型名称</label><input id="ai-model" placeholder="填写服务商提供的模型 ID"><label class="label" for="ai-key" style="margin-top:12px">API 密钥 / 留空保留已保存密钥</label><input id="ai-key" type="password" autocomplete="new-password" placeholder="只写入，不会回显"><p id="ai-key-state" class="sub">密钥状态尚未读取。</p><div class="actions"><button id="ai-save" class="primary">保存并设为当前</button></div><p class="source-note">支持本项目方案 JSON 与兼容服务商字段。Claude 专用协议、SQL 数据库导出或 OAuth 凭据不能直接作为兼容接口使用；不会自动读取本机 CC Switch 的密钥。</p></div></div>
<div class="panel"><div class="panel-head"><h2>回复规则</h2><button id="ai-prompt-import">导入提示词</button><input id="ai-prompt-file" type="file" accept=".txt,.md,text/plain" hidden></div><div class="panel-body"><label class="label" for="ai-prompt">系统提示词</label><textarea id="ai-prompt" maxlength="20000"></textarea><label class="label" for="ai-contacts" style="margin-top:12px">自动回复白名单 / 私聊，每行一人，最多 10 人</label><textarea id="ai-contacts" placeholder="未选择联系人时不能启用。"></textarea><div class="actions" style="margin:12px 0"><button id="ai-use-targets">使用当前朋友圈所选名单</button><button id="ai-read-contacts">读取微信联系人</button></div><label class="label" for="ai-contact-search">搜索并勾选联系人</label><input id="ai-contact-search" placeholder="联系人昵称 / 备注"><div id="ai-contact-list" class="contact-list"><div class="empty">读取联系人后可搜索勾选，也可直接填写白名单。</div></div><div class="form-grid"><label class="field"><span class="label">同一联系人回复间隔 / 秒</span><input id="ai-interval" type="number" min="5" max="3600" value="15"></label><label class="field"><span class="label">每小时最多回复</span><input id="ai-hour-limit" type="number" min="1" max="120" value="20"></label><label class="field"><span class="label">本次托管时长 / 分钟</span><input id="ai-minutes" type="number" min="1" max="480" value="60"></label><label class="field"><span class="label">微信账号 / 多账号时精确指定</span><input id="ai-account" placeholder="SDK 读取的账号名"></label></div><p class="hint">启用后，选中私聊的新消息会发往当前配置的 AI 服务，并把生成内容回复到对应微信会话。历史消息、自己发出的消息和群聊不会自动回复。首次启动会建立历史基线。</p><div class="actions"><button id="ai-start" class="primary">启用智能回复</button><button id="ai-stop" class="danger">停止智能回复</button></div><p class="sub">启用前先保存并预览。此功能默认关闭，重启后需手动启用。</p></div></div>
<div class="panel wide"><div class="panel-head"><h2>回复预览</h2><span class="sub">只生成样例，不发送到微信</span></div><div class="panel-body"><label class="label" for="ai-sample">样例消息</label><textarea id="ai-sample" maxlength="8000" placeholder="输入一条样例消息，检查所选服务商和提示词。"></textarea><div class="actions" style="margin:12px 0"><button id="ai-preview">生成预览</button></div><pre id="ai-result" tabindex="0">未调用 AI 服务。</pre></div></div></div></section>'''

SCRIPT = r'''<script>
(()=>{
let targetNames=[],targetSelection=new Set(),targetLoaded=false,targetDirty=true,aiConfig=null,aiChosen='',aiLoading=false,aiStatusBusy=false,contactNames=[],aiRunning=false;
const unique=values=>[...new Set(values.map(v=>String(v).trim()).filter(Boolean))];
function selectedSummary(){ $('target-summary').textContent='已选择 '+targetSelection.size+' 位用户';$('targets-start').disabled=!connected||targetDirty||targetSelection.size===0;}
function targetChanged(){targetDirty=true;$('targets-state').textContent='名单已修改，请保存后启动。';selectedSummary();}
function contactList(container,names,selected,search,onChange){const query=search.trim().toLocaleLowerCase('zh-CN');const matching=names.filter(n=>n.toLocaleLowerCase('zh-CN').includes(query));container.replaceChildren();for(const name of matching){const label=el('label',undefined,'contact-choice'),check=document.createElement('input');check.type='checkbox';check.checked=selected.has(name);check.onchange=()=>onChange(name,check.checked);label.append(check,el('span',name));container.append(label);}if(!matching.length)container.append(el('div',names.length?'没有匹配的用户。':'还没有联系人。可手动添加，或从已登录微信读取。','empty'));}
function renderTargets(){contactList($('target-list'),targetNames,targetSelection,$('target-search').value,(name,on)=>{on?targetSelection.add(name):targetSelection.delete(name);targetChanged();});selectedSummary();}
async function loadTargets(){try{const r=await api('/api/config');targetSelection=new Set(r.config.replica_authors?.length?r.config.replica_authors:r.config.replica_author?[r.config.replica_author]:[]);targetNames=unique([...targetNames,...targetSelection]);$('target-keyword').value=r.config.replica_keyword||'';targetDirty=false;targetLoaded=true;renderTargets();$('targets-state').textContent='已读取电脑端所选名单。';}catch(e){notice(e.message,true);}}
async function readContacts(button){button.disabled=true;try{const r=await api('/api/sdk/contacts');const names=unique((r.data||[]).flatMap(account=>account.names||[]));contactNames=unique([...contactNames,...names]);targetNames=unique([...targetNames,...names]);renderTargets();renderAiContacts();notice('已读取 '+names.length+' 个联系人姓名'+((r.data||[]).some(a=>a.truncated)?'；SDK 返回结果有截断。':'。'));}catch(e){notice('读取联系人失败：'+e.message,true);}finally{button.disabled=false;}}
$('target-search').oninput=renderTargets;$('targets-read').onclick=e=>readContacts(e.currentTarget);$('targets-add').onclick=()=>{const names=unique($('target-manual').value.split(/\r?\n/));if(!names.length)return;if(unique([...targetSelection,...names]).length>100){notice('一次最多选择 100 位用户。',true);return;}for(const name of names){targetSelection.add(name);if(!targetNames.includes(name))targetNames.push(name);}$('target-manual').value='';targetChanged();renderTargets();};$('targets-clear').onclick=()=>{targetSelection.clear();targetChanged();renderTargets();};$('target-keyword').oninput=targetChanged;
async function saveTargets(){await api('/api/config',{replica_authors:[...targetSelection],replica_author:'',replica_keyword:$('target-keyword').value.trim()});targetDirty=false;selectedSummary();$('targets-state').textContent='已保存 '+targetSelection.size+' 位用户；尚未启动任务。';notice('朋友圈用户选择已保存到电脑端。');}
$('targets-save').onclick=async e=>{e.currentTarget.disabled=true;try{await saveTargets();}catch(error){notice(error.message,true);}finally{e.target.disabled=false;}};$('targets-start').onclick=async e=>{if(targetDirty||!targetSelection.size)return;const button=e.currentTarget;button.disabled=true;try{const r=await api('/api/task/start',{task:'replica_like'});notice(r.message);$('targets-state').textContent='定点任务已提交，请在任务控制中查看实际日志和退出状态。';await refresh();}catch(error){notice(error.message,true);}finally{selectedSummary();}};
function renderAiContacts(){const selection=new Set(unique($('ai-contacts').value.split(/\r?\n/)));contactList($('ai-contact-list'),unique([...contactNames,...selection]),selection,$('ai-contact-search').value,(name,on)=>{if(on&&selection.size>=10){notice('智能回复最多选择 10 位私聊联系人。',true);renderAiContacts();return;}on?selection.add(name):selection.delete(name);$('ai-contacts').value=[...selection].join('\n');renderAiContacts();});}
$('ai-contact-search').oninput=renderAiContacts;$('ai-contacts').oninput=renderAiContacts;$('ai-read-contacts').onclick=e=>readContacts(e.currentTarget);$('ai-use-targets').onclick=async()=>{if(!targetLoaded)await loadTargets();if(targetSelection.size>10){notice('当前朋友圈名单超过 10 人，请在智能回复白名单中选择最多 10 位。',true);return;}$('ai-contacts').value=[...targetSelection].join('\n');renderAiContacts();};
function profileFields(){const p=aiConfig?.profiles.find(p=>p.id===aiChosen);if(!p)return;$('ai-name').value=p.name||'';$('ai-protocol').value=p.protocol||'openai-compatible';$('ai-url').value=p.baseUrl||'';$('ai-model').value=p.model||'';$('ai-key').value='';$('ai-key-state').textContent=p.hasApiKey?'已保存密钥 / 不会回显，留空保留。':'尚未保存密钥；本地服务可按其要求留空。';$('ai-active').textContent='当前启用：'+(aiConfig.profiles.find(p=>p.id===aiConfig.activeProfileId)?.name||'无');}
function renderAiConfig(config){aiConfig=config;aiChosen=config.activeProfileId||config.profiles[0]?.id||'';$('ai-profile').replaceChildren(...config.profiles.map(p=>{const option=el('option',p.name||p.id);option.value=p.id;return option;}));$('ai-profile').value=aiChosen;profileFields();$('ai-prompt').value=config.systemPrompt||'';$('ai-contacts').value=(config.allowedContacts||[]).join('\n');$('ai-interval').value=config.minReplySeconds||15;$('ai-hour-limit').value=config.maxRepliesPerHour||20;$('ai-minutes').value=config.sessionMinutes||60;$('ai-account').value=config.account||'';renderAiContacts();}
async function loadAi(){if(aiLoading)return;aiLoading=true;try{const r=await api('/api/sdk/ai/config');renderAiConfig(r.config);await pollAi();}catch(e){$('ai-state').textContent='AI 配置未就绪：'+e.message;notice('请先启动 SDK 服务，再读取 AI 配置。',true);}finally{aiLoading=false;}}
function aiPayload(){if(!aiConfig)throw new Error('请先启动 SDK 并刷新配置。');const profiles=aiConfig.profiles.map(p=>({id:p.id,name:p.name,protocol:p.protocol,baseUrl:p.baseUrl,model:p.model,apiKeyEnv:p.apiKeyEnv||''}));const profile=profiles.find(p=>p.id===aiChosen);if(!profile)throw new Error('请先新增或选择服务商。');Object.assign(profile,{name:$('ai-name').value.trim(),protocol:$('ai-protocol').value,baseUrl:$('ai-url').value.trim(),model:$('ai-model').value.trim()});if($('ai-key').value)profile.apiKey=$('ai-key').value;return {activeProfileId:aiChosen,profiles,systemPrompt:$('ai-prompt').value,allowedContacts:unique($('ai-contacts').value.split(/\r?\n/)),account:$('ai-account').value.trim(),allowGroups:false,minReplySeconds:Number($('ai-interval').value),maxRepliesPerHour:Number($('ai-hour-limit').value),sessionMinutes:Number($('ai-minutes').value)};}
async function saveAi(){const r=await api('/api/sdk/ai/config',aiPayload());$('ai-key').value='';renderAiConfig(r.config);notice('AI 服务商与回复规则已保存。');}
async function pollAi(){if(aiStatusBusy)return;aiStatusBusy=true;try{const r=await api('/api/sdk/ai/status');aiRunning=Boolean(r.running);$('ai-state').textContent=(r.running?'智能回复运行中':'智能回复未启用')+' · '+r.state+' · 已回复 '+(r.replyCount||0)+' 条'+(r.lastError?' · '+r.lastError:'');$('ai-start').disabled=aiRunning;$('ai-stop').disabled=!aiRunning;for(const id of ['ai-save','ai-import','ai-new','ai-profile'])$(id).disabled=aiRunning;}catch(e){$('ai-state').textContent='SDK / AI 状态不可用：'+e.message;}finally{aiStatusBusy=false;}}
async function aiAction(button,work){button.disabled=true;try{await work();}catch(e){notice(e.message,true);}finally{button.disabled=false;}}
$('ai-profile').onchange=e=>{aiChosen=e.target.value;profileFields();};$('ai-new').onclick=()=>{if(!aiConfig){notice('请先启动 SDK 并读取配置。',true);return;}const p={id:'provider_'+Date.now(),name:'新服务商',protocol:'openai-compatible',baseUrl:'',model:'',apiKeyEnv:''};aiConfig.profiles.push(p);const option=el('option',p.name);option.value=p.id;$('ai-profile').append(option);$('ai-profile').value=aiChosen=p.id;profileFields();};$('ai-reload').onclick=loadAi;$('ai-sdk-start').onclick=e=>aiAction(e.currentTarget,async()=>{await api('/api/sdk/start',{});await loadAi();});$('ai-save').onclick=e=>aiAction(e.currentTarget,saveAi);
$('ai-preview').onclick=e=>aiAction(e.currentTarget,async()=>{if(!$('ai-sample').value.trim())throw new Error('请输入样例消息。');await saveAi();$('ai-result').textContent='正在生成预览…';const r=await api('/api/sdk/ai/preview',{message:$('ai-sample').value});$('ai-result').textContent=r.reply||'服务没有返回回复。';notice('回复预览已生成，未发送到微信。');});$('ai-start').onclick=e=>aiAction(e.currentTarget,async()=>{await saveAi();const r=await api('/api/sdk/ai/start',{});notice(r.message);await pollAi();});$('ai-stop').onclick=e=>aiAction(e.currentTarget,async()=>{const r=await api('/api/sdk/ai/stop',{});notice(r.message);await pollAi();});
$('ai-import').onclick=()=>$('ai-import-file').click();$('ai-import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>50000)throw new Error('配置文件请限制在 50 KB 以内。');const json=await file.text();JSON.parse(json);const r=await api('/api/sdk/ai/profiles/import',{json});renderAiConfig(r.config);notice('配置已导入；不会自动启用智能回复。');}catch(error){notice('导入失败：'+error.message,true);}finally{e.target.value='';}};
$('ai-export').onclick=e=>aiAction(e.currentTarget,async()=>{const r=await api('/api/sdk/ai/profiles/export');const link=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(r.config,null,2)],{type:'application/json'}));link.href=url;link.download='wechat-ai-profiles-without-keys.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('已导出不含密钥的配置。');});$('ai-prompt-import').onclick=()=>$('ai-prompt-file').click();$('ai-prompt-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>50000)throw new Error('提示词文件过大。');const text=await file.text();if(text.length>20000)throw new Error('提示词最多 20000 字。');$('ai-prompt').value=text;notice('提示词已读入，请保存方案。');}catch(error){notice(error.message,true);}finally{e.target.value='';}};
const subtitles={tasks:'查看每个任务的状态，让操作有迹可循。',sdk:'连接官方微信，管理本机 SDK 与插件。',devices:'检测已连接的安卓手机与模拟器。',settings:'保存电脑端参数，下次任务启动时生效。',targets:'选择指定用户，再启动定点点赞任务。',ai:'管理 AI 服务商，先预览再启用智能答复。'};document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('.top .sub').textContent=subtitles[button.dataset.view];button.scrollIntoView({block:'nearest',inline:'nearest'});}));$('tab-targets').addEventListener('click',()=>loadTargets());$('tab-ai').addEventListener('click',loadAi);if(currentView==='targets')loadTargets();if(currentView==='ai')loadAi();setInterval(()=>{if(currentView==='ai'&&!document.hidden&&connected)pollAi();},3000);
})();
</script>'''

def add_features(page):
    page = page.replace('</head>', STYLE + '</head>')
    page = page.replace('</nav>', NAV + '</nav>', 1)
    page = page.replace('<footer class="footer">', PANELS + '<footer class="footer">', 1)
    page = page.replace("['sdk','devices','settings'].includes(requestedView)", "['sdk','devices','settings','targets','ai'].includes(requestedView)")
    return page.replace('</body>', SCRIPT + '</body>')
